
/* ---- the airport from OpenStreetMap: grass, taxiways, aprons, stands, jet bridges and buildings ---- */
// Geometry comes from OPLA_OSM (generated by scripts/osm-airport.mjs, © OpenStreetMap contributors, ODbL).
// The runways themselves come from the published threshold coordinates in b_core.js.
// Building heights are typical values, and the terminal facade, the mosque dome and the tower are simplified.
const OSM_BOX={x0:-1840,x1:2100,z0:-2880,z1:2990};
let BOUNDARY=OPLA_OSM.boundary||null;
// is a point within 250 m of the aerodrome, or in a 60 m cell that OSM already has buildings in?
function nearAerodrome(x,z){for(const [dx,dz] of [[0,0],[250,0],[-250,0],[0,250],[0,-250]])if(inBoundary(x+dx,z+dz))return true;return false;}
let OSM_CELLS=null;function osmBuilt(x,z){if(!OSM_CELLS){OSM_CELLS=new Set();for(const b of OPLA_OSM.buildings){const p=b[2];OSM_CELLS.add(Math.floor(p[0]/60)+','+Math.floor(p[1]/60));}}return OSM_CELLS.has(Math.floor(x/60)+','+Math.floor(z/60));}
function inBoundary(x,z){return BOUNDARY?pointInPoly(x,z,BOUNDARY):Math.abs(x+120)<1400&&Math.abs(z)<2800;}
function shapeFrom(flat){const s=new THREE.Shape();for(let i=0;i<flat.length;i+=2){const x=flat[i],y=-flat[i+1];i?s.lineTo(x,y):s.moveTo(x,y);}return s;}
function flatShape(flat,mat,y){const g=new THREE.ShapeGeometry(shapeFrom(flat));g.rotateX(-Math.PI/2);const m=new THREE.Mesh(g,mat);m.position.y=y;m.receiveShadow=true;scene.add(m);return m;}
// many ribbons (taxiways, centrelines) merged into one mesh
function ribbons(list,y,mat){const pos=[],idx=[];let base=0;
  for(const [pts,w] of list){for(let i=0;i<pts.length;i++){const p=pts[i],q=pts[Math.min(i+1,pts.length-1)],o=pts[Math.max(i-1,0)];let dx=q[0]-o[0],dz=q[1]-o[1];const l=Math.hypot(dx,dz)||1;dx/=l;dz/=l;
      pos.push(p[0]-dz*w/2,y,p[1]+dx*w/2,p[0]+dz*w/2,y,p[1]-dx*w/2);if(i<pts.length-1){const a=base+i*2;idx.push(a,a+2,a+1,a+1,a+2,a+3);}}
    // round the ends so junctions look joined up
    base+=pts.length*2;}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setIndex(idx);g.computeVertexNormals();
  const uv=[];for(let i=0;i<pos.length;i+=3)uv.push(pos[i]/24,pos[i+2]/24);g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  const m=new THREE.Mesh(g,mat);m.receiveShadow=true;scene.add(m);return m;}
// Merge a built group (a parked aircraft) into one mesh per material, so it costs a handful of draw calls.
function mergeStatic(root){root.updateMatrixWorld(true);const buckets=new Map();
  root.traverse(o=>{if(!o.isMesh)return;let v=o;while(v){if(!v.visible)return;v=v.parent;}
    let g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);
    const k=o.material.uuid;if(!buckets.has(k))buckets.set(k,{m:o.material,gs:[]});buckets.get(k).gs.push(g);});
  const out=[];for(const {m,gs} of buckets.values()){let n=0;for(const g of gs)n+=g.attributes.position.count;
    const P=new Float32Array(n*3),N=new Float32Array(n*3),U=new Float32Array(n*2),C=m.vertexColors?new Float32Array(n*3):null;let o=0;
    for(const g of gs){const c=g.attributes.position.count;P.set(g.attributes.position.array,o*3);if(!g.attributes.normal)g.computeVertexNormals();N.set(g.attributes.normal.array,o*3);
      if(g.attributes.uv)U.set(g.attributes.uv.array,o*2);if(C){if(g.attributes.color)C.set(g.attributes.color.array,o*3);else C.fill(1,o*3,(o+c)*3);}o+=c;}
    const G2=new THREE.BufferGeometry();G2.setAttribute('position',new THREE.BufferAttribute(P,3));G2.setAttribute('normal',new THREE.BufferAttribute(N,3));G2.setAttribute('uv',new THREE.BufferAttribute(U,2));if(C)G2.setAttribute('color',new THREE.BufferAttribute(C,3));
    const mesh=new THREE.Mesh(G2,m);mesh.castShadow=true;mesh.receiveShadow=true;scene.add(mesh);out.push(mesh);}
  return out;}
// facade of the main terminal: a row of pointed arches in buff stone over tinted glass (simplified)
function terminalTex(){return tex(256,128,(c,w,h)=>{c.fillStyle='#ddd2b8';c.fillRect(0,0,w,h);
  c.fillStyle='#3f5562';c.beginPath();const ax=w*0.18,aw=w*0.64,top=h*0.2,spring=h*0.42;c.moveTo(ax,h*0.92);c.lineTo(ax,spring);c.quadraticCurveTo(ax,top+h*0.06,ax+aw/2,top);c.quadraticCurveTo(ax+aw,top+h*0.06,ax+aw,spring);c.lineTo(ax+aw,h*0.92);c.closePath();c.fill();
  c.strokeStyle='rgba(235,229,210,.7)';c.lineWidth=2;for(let y=spring+10;y<h*0.92;y+=14){c.beginPath();c.moveTo(ax,y);c.lineTo(ax+aw,y);c.stroke();}c.beginPath();c.moveTo(ax+aw/2,top+4);c.lineTo(ax+aw/2,h*0.92);c.stroke();
  c.fillStyle='#c9bc9e';c.fillRect(0,h*0.92,w,h*0.08);c.fillRect(0,0,w,h*0.07);});}
// extrude building footprints into one mesh per material
function extrude(list,mat,colorFn,uvScale){const pos=[],nor=[],col=[],uv=[];const tmp=new THREE.Color();
  for(const b of list){const [h,,p]=b;const n=p.length/2;let per=0;colorFn(b,tmp);
    // walls
    let A=0;for(let i=0;i<n;i++){const j=(i+1)%n;A+=p[i*2]*p[j*2+1]-p[j*2]*p[i*2+1];}const ccw=A>0;
    for(let i=0;i<n;i++){const j=(i+1)%n;const x0=p[i*2],z0=p[i*2+1],x1=p[j*2],z1=p[j*2+1];const L=Math.hypot(x1-x0,z1-z0);if(L<0.01)continue;
      let nx=(z1-z0)/L,nz=-(x1-x0)/L;if(!ccw){nx=-nx;nz=-nz;}
      const quad=[[x0,0,z0],[x1,0,z1],[x1,h,z1],[x0,0,z0],[x1,h,z1],[x0,h,z0]];const us=[per,per+L,per+L,per,per+L,per],vs=[0,0,h,0,h,h];
      const ord=ccw?[0,2,1,3,5,4]:[0,1,2,3,4,5];for(const k of ord){pos.push(...quad[k]);nor.push(nx,0,nz);col.push(tmp.r,tmp.g,tmp.b);uv.push(us[k]/(uvScale||10),vs[k]/h);}per+=L;}
    // roof
    const v2=[];for(let i=0;i<n;i++)v2.push(new THREE.Vector2(p[i*2],p[i*2+1]));const tris=THREE.ShapeUtils.triangulateShape(v2,[]);
    const rc=tmp.clone().multiplyScalar(0.86);for(const t of tris){const o=ccw?[0,1,2]:[0,2,1];for(const k of o){const q=v2[t[k]];pos.push(q.x,h,q.y);nor.push(0,1,0);col.push(rc.r,rc.g,rc.b);uv.push(0.5,0.98);}}}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(nor,3));
  g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  const m=new THREE.Mesh(g,mat);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m;}
function buildAirportOSM(D,M){
  // aerodrome grass inside the real boundary
  if(D.boundary){BOUNDARY=D.boundary;const gt=M.grass.map.clone();gt.needsUpdate=true;gt.repeat.set(0.01,0.01);flatShape(D.boundary,new THREE.MeshLambertMaterial({map:gt}),0.05);}
  // aprons
  const ct=M.concrete.clone();ct.needsUpdate=true;ct.repeat.set(1/24,1/24);const apronM=new THREE.MeshLambertMaterial({map:ct});
  for(const [,p] of D.aprons){flatShape(p,apronM,0.1);let b=[1e9,-1e9,1e9,-1e9];for(let i=0;i<p.length;i+=2){b=[Math.min(b[0],p[i]),Math.max(b[1],p[i]),Math.min(b[2],p[i+1]),Math.max(b[3],p[i+1])];}PAVE.polys.push({p,b});}
  for(const s of D.stopways){const pts=[];for(let i=0;i<s.length;i+=2)pts.push([s[i],s[i+1]]);}
  // taxiways with yellow centrelines and blue edge lights
  const at=M.asphalt.clone();at.needsUpdate=true;at.repeat.set(1,1);const twM=new THREE.MeshLambertMaterial({map:at,polygonOffset:true,polygonOffsetFactor:-1});
  const yl=new THREE.MeshBasicMaterial({color:'#e6b830',polygonOffset:true,polygonOffsetFactor:-3,polygonOffsetUnits:-3});
  const tw=[],cl=[],lights=[];
  for(const [ref,w,f] of D.taxiways){const pts=[];for(let i=0;i<f.length;i+=2)pts.push([f[i],f[i+1]]);if(pts.length<2)continue;
    // stand lead-ins on the apron are painted lines on concrete, not asphalt
    const mid=pts[Math.floor(pts.length/2)],onApron=PAVE.polys.some(a=>pointInPoly(mid[0],mid[1],a.p));if(!onApron)tw.push([pts,w]);cl.push([pts,onApron?0.25:0.35]);
    for(let i=0;i<pts.length-1;i++){const [x0,z0]=pts[i],[x1,z1]=pts[i+1];const L=Math.hypot(x1-x0,z1-z0);const seg=[x0,z0,x1,z1,w/2+4];
      for(let bx=Math.floor(Math.min(x0,x1)/100)-1;bx<=Math.floor(Math.max(x0,x1)/100)+1;bx++)for(let bz=Math.floor(Math.min(z0,z1)/100)-1;bz<=Math.floor(Math.max(z0,z1)/100)+1;bz++){const k=bx+','+bz;if(!PAVE.segs.has(k))PAVE.segs.set(k,[]);PAVE.segs.get(k).push(seg);}
      const nx=-(z1-z0)/L,nz=(x1-x0)/L;for(let d=0;d<L;d+=50)for(const s of [-1,1])lights.push([x0+(x1-x0)*d/L+nx*s*(w/2+1),0.4,z0+(z1-z0)*d/L+nz*s*(w/2+1),'#3060ff']);}}
  ribbons(tw,0.11,twM);ribbons(cl,0.14,yl);lightPoints(lights,3.5,true);
  // buildings: the main terminal, hangars and cargo sheds, and the houses and offices around the airport
  const term=[],hang=[],other=[];let mainTerm=null;
  for(const b of D.buildings){const [h,k,p]=b;if(k==='t'){term.push(b);if(!mainTerm||p.length&&area2(p)>area2(mainTerm[2]))mainTerm=b;}else if(k==='h')hang.push(b);else other.push(b);
    let x0=1e9,x1=-1e9,z0=1e9,z1=-1e9;for(let i=0;i<p.length;i+=2){x0=Math.min(x0,p[i]);x1=Math.max(x1,p[i]);z0=Math.min(z0,p[i+1]);z1=Math.max(z1,p[i+1]);}addObstacle(x0,x1,z0,z1,h);}
  const pal=['#d8ccb2','#cbbd9f','#e2dccb','#bfae92','#d3c3a6','#b9a385','#e6e0d2','#c4a78a'];
  const vc=new THREE.MeshLambertMaterial({vertexColors:true});
  extrude(other,vc,(b,c)=>{const r=hash(b[2][0]*0.13+b[2][1]*0.71);c.set(pal[Math.floor(r*pal.length)]);c.multiplyScalar(0.88+hash(r*7)*0.2);if(b[1]==='m')c.set('#efe9dc');});
  extrude(hang,new THREE.MeshStandardMaterial({vertexColors:true,metalness:0.4,roughness:0.5}),(b,c)=>c.set('#b9bdb8'));
  const tt=terminalTex();tt.wrapS=THREE.RepeatWrapping;
  extrude(term,new THREE.MeshLambertMaterial({map:tt,vertexColors:true}),(b,c)=>c.set('#ffffff'),9);
  // a roof slab and the landside departures canopy on the main terminal
  if(mainTerm){const p=mainTerm[2],h=mainTerm[0];let x0=1e9,x1=-1e9,z0=1e9,z1=-1e9;for(let i=0;i<p.length;i+=2){x0=Math.min(x0,p[i]);x1=Math.max(x1,p[i]);z0=Math.min(z0,p[i+1]);z1=Math.max(z1,p[i+1]);}
    const roofM=new THREE.MeshStandardMaterial({color:'#c3c6c4',metalness:0.5,roughness:0.4});box(x1-x0+8,1.6,z1-z0+8,roofM,(x0+x1)/2,h,(z0+z1)/2);
    box(14,1.0,(z1-z0)*0.8,roofM,x1+7,9,(z0+z1)/2);for(let z=z0+40;z<z1-40;z+=24)box(0.8,9,0.8,roofM,x1+12,0,z);
    W3.terminal={x:(x0+x1)/2,z:(z0+z1)/2};}
  // mosques: a simple dome and minaret pair (simplified)
  const domeM=new THREE.MeshStandardMaterial({color:'#f2efe6',roughness:0.5});
  for(const b of other){if(b[1]!=='m')continue;const p=b[2];let cx=0,cz=0;const n=p.length/2;for(let i=0;i<p.length;i+=2){cx+=p[i];cz+=p[i+1];}cx/=n;cz/=n;const r=Math.sqrt(area2(p))*0.18;
    if(r<3)continue;const d=new THREE.Mesh(new THREE.SphereGeometry(r,16,10,0,Math.PI*2,0,Math.PI/2),domeM);d.position.set(cx,b[0],cz);d.castShadow=true;scene.add(d);}
  // jet bridges: tunnels on supports at the departure level
  const jb=new THREE.MeshStandardMaterial({color:'#9aa0a3',metalness:0.5,roughness:0.45});
  for(const f of D.bridges){for(let i=0;i<f.length-2;i+=2){const x0=f[i],z0=f[i+1],x1=f[i+2],z1=f[i+3];const L=Math.hypot(x1-x0,z1-z0);const m=new THREE.Mesh(new THREE.BoxGeometry(L,3,3.2),jb);m.position.set((x0+x1)/2,4.6,(z0+z1)/2);m.rotation.y=-Math.atan2(z1-z0,x1-x0);m.castShadow=true;scene.add(m);
      const leg=box(0.6,3.2,0.6,jb,x1,0,z1);leg.castShadow=false;}}
  // the control tower: placement unverified (an untagged OSM tower west of the runways), shape simplified
  const tp=geo(31.52281,74.39831);const white=new THREE.MeshLambertMaterial({color:'#e8e4da'}),glass=new THREE.MeshStandardMaterial({color:'#4f6a78',metalness:0.6,roughness:0.25});
  const shaft=new THREE.Mesh(new THREE.CylinderGeometry(4,5,40,16),white);shaft.position.set(tp.x,20,tp.z);shaft.castShadow=true;scene.add(shaft);
  const cab=new THREE.Mesh(new THREE.CylinderGeometry(9,7,6,8),glass);cab.position.set(tp.x,43,tp.z);scene.add(cab);const rf=new THREE.Mesh(new THREE.CylinderGeometry(10,10,1.2,8),white);rf.position.set(tp.x,46.6,tp.z);scene.add(rf);
  addObstacle(tp.x-10,tp.x+10,tp.z-10,tp.z+10,48);W3.towerTop=new THREE.Vector3(tp.x,44,tp.z);
  // parked airliners on the real stands, noses to the terminal (generic house colours)
  const types=['a320','b738','b77w','a320','b789','a359','b738','a320'];let n=0;const used=[];
  const stands=D.stands.filter(s=>s[0]>450&&s[0]<640).sort((a,b)=>a[1]-b[1]);
  for(const s of stands){if(n>=types.length)break;if(used.some(u=>Math.abs(u-s[1])<60))continue;const sp=AIRCRAFT_BY_ID[types[n]]||AIRCRAFT.find(a=>a.id===types[n]);if(!sp)continue;
    const A=buildAirliner(sp);setAircraftState(A,{spec:sp,rpm:0,engineMax:1,v:0,flapPos:0,sweep:0,gearPos:1,ab:0,spd:0,gsp:0},0);
    const hdg=Math.PI/2;A.g.position.set(s[0]-sp.noseX*Math.sin(hdg),sp.gearH,s[1]+sp.noseX*Math.cos(hdg));A.g.rotation.y=Math.PI/2-hdg;
    mergeStatic(A.g);addObstacle(A.g.position.x-sp.len/2,A.g.position.x+sp.len/2,s[1]-sp.span/2,s[1]+sp.span/2,14);used.push(s[1]);n++;}
}
function area2(p){let a=0;const n=p.length/2;for(let i=0;i<n;i++){const j=(i+1)%n;a+=p[i*2]*p[j*2+1]-p[j*2]*p[i*2+1];}return Math.abs(a/2);}
